import Link from "next/link";

export default function Navbar({ data }) {
  return (
    <nav
      style={{
        padding: "16px 32px",
        background: "#111",
        color: "#fff",
        display: "flex",
        gap: "18px",
        alignItems: "center"}}
    >
      <Link
        href="/"
        style={{
          color: "#fff",
          textDecoration: "none",
          fontSize: "20px",
          fontWeight: "bold"}}
      >
        {data?.navbar?.title ?? "My Website"}
      </Link>
      <Link href="/services" style={{}}>
        Services
      </Link>
      <Link href="/contact" style={{}}>
        Contact
      </Link>
    </nav>
  );
}

